"""Runtime support for vecDSL programs generated for PostgreSQL with pgvector, through psycopg 3. Generated by vecDSL 7. Do not edit.

Every statement arrives as SQL text with numbered parameters ($1, $2, ...), identical in the Python, TypeScript and Java
programs. Parameters are sent as text (lists and objects as JSON text) and cast in the SQL; queries return one json value per
row. Each call runs in its own transaction, opened with BEGIN on a connection in autocommit mode, so that SET LOCAL settings
(set_config(name, value, true)) never outlive the statement.
"""

from __future__ import annotations

import json
import math
import os
import re
from importlib.metadata import PackageNotFoundError, version
from typing import Any, NoReturn, Sequence
from urllib.parse import unquote, urlparse

SDK_PACKAGE = "psycopg"
SDK_MIN = "{{sdk.python.min}}"
SDK_MAX = "{{sdk.python.max}}"

_DIGITS = 6
_BATCH = 500
_PLACEHOLDER = re.compile(r"\$(\d+)")
_ISOLATION = {"read_uncommitted": "READ UNCOMMITTED", "read_committed": "READ COMMITTED", "repeatable_read": "REPEATABLE READ",
              "serializable": "SERIALIZABLE"}


class UnsupportedFeature(NotImplementedError):
    pass


def _version_tuple(text: str) -> tuple[int, ...]:
    parts = []
    for token in re.split(r"[.+\-]", text.lstrip("v")):
        if not token.isdigit():
            break
        parts.append(int(token))
    return tuple(parts)


def requirement() -> str:
    return f"{SDK_PACKAGE}[binary]>={SDK_MIN},<{SDK_MAX}"


def check_sdk() -> str:
    try:
        installed = version(SDK_PACKAGE)
    except PackageNotFoundError as error:
        raise ImportError(f"{SDK_PACKAGE} is not installed; install '{requirement()}'") from error
    if not _version_tuple(SDK_MIN) <= _version_tuple(installed) < _version_tuple(SDK_MAX):
        raise ImportError(f"{SDK_PACKAGE} {installed} is not supported; install '{requirement()}'")
    return installed


check_sdk()

import psycopg  # noqa: E402


def unsupported(vendor: str, feature: str) -> NoReturn:
    raise UnsupportedFeature(f"{feature} is not supported for target {vendor}")


def env(name: str) -> str:
    value = os.environ.get(name)
    if value is None:
        raise KeyError(f"environment variable {name} is not set")
    return value


class Client:
    """The server endpoint and one connection per database the program uses; the password comes from the environment."""

    def __init__(self, url: str, password_variable: str) -> None:
        parsed = urlparse(url)
        if parsed.scheme not in ("postgresql", "postgres"):
            raise ValueError(f"expected a postgresql:// URI, got {url!r}")
        if parsed.password is not None:
            raise ValueError("the connection URI must not contain a password; set it in the environment")
        self.host = parsed.hostname or "127.0.0.1"
        self.port = parsed.port or 5432
        self.user = unquote(parsed.username or "postgres")
        self.database = unquote(parsed.path.lstrip("/")) or self.user
        self.options = dict(part.split("=", 1) for part in parsed.query.split("&") if "=" in part)
        self.options.setdefault("connect_timeout", "10")
        self.password = os.environ.get(password_variable)
        self._connections: dict[str, psycopg.Connection[Any]] = {}

    def connection(self, database: str | None = None) -> psycopg.Connection[Any]:
        name = database or self.database
        if name not in self._connections:
            connection = psycopg.connect(host=self.host, port=self.port, user=self.user, password=self.password, dbname=name,
                                         autocommit=True, **self.options)
            connection.execute("CREATE EXTENSION IF NOT EXISTS vector")
            self._connections[name] = connection
        return self._connections[name]

    def forget(self, database: str) -> None:
        connection = self._connections.pop(database, None)
        if connection is not None:
            connection.close()

    def close(self) -> None:
        for connection in self._connections.values():
            connection.close()
        self._connections.clear()


def connect(url: str, password_variable: str = "VECDSL_PGVECTOR_PASSWORD") -> Client:
    return Client(url, password_variable)


def _plain(value: Any) -> Any:
    """Integral floats as integers, so that JSON text reads 35, not 35.0, in every host language."""
    if isinstance(value, float) and value.is_integer() and math.isfinite(value) and abs(value) < 1e15:
        return int(value)
    if isinstance(value, (list, tuple)):
        return [_plain(item) for item in value]
    if isinstance(value, dict):
        return {str(key): _plain(item) for key, item in value.items()}
    return value


def _text(value: Any) -> str | None:
    """A parameter as text: strings as they are, booleans and numbers in JSON form, lists and objects as JSON."""
    if value is None or isinstance(value, str):
        return value
    return json.dumps(_plain(value), separators=(",", ":"), ensure_ascii=False)


def _statement(sql: str, params: Sequence[Any]) -> tuple[str, dict[str, str | None]]:
    """psycopg's named placeholders for $n (a number may repeat), with literal percent signs escaped."""
    text = _PLACEHOLDER.sub(lambda match: f"%(p{match.group(1)})s", sql.replace("%", "%%"))
    return text, {f"p{index}": _text(value) for index, value in enumerate(params, start=1)}


def _value(value: Any) -> Any:
    """Result values in one form for every host language: floats rounded, integral floats as integers."""
    if isinstance(value, float):
        rounded = round(value, _DIGITS)
        return int(rounded) if rounded.is_integer() else rounded
    if isinstance(value, list):
        return [_value(item) for item in value]
    if isinstance(value, dict):
        return {key: _value(item) for key, item in value.items()}
    return value


def _run(cursor: psycopg.Cursor[Any], sql: str, params: Sequence[Any]) -> list[Any]:
    text, values = _statement(sql, params)
    cursor.execute(text, values)
    return [_value(row[0]) for row in cursor.fetchall()] if cursor.description else []


def _begin(cursor: psycopg.Cursor[Any], isolation: str | None, settings: dict[str, str] | None) -> None:
    cursor.execute("BEGIN" + (f" ISOLATION LEVEL {_ISOLATION[isolation]}" if isolation else ""))
    for name, setting in (settings or {}).items():
        cursor.execute("SELECT set_config(%(name)s, %(value)s, true)", {"name": name, "value": setting})


def _transaction(client: Client, steps: Sequence[dict[str, Any]], database: str | None, isolation: str | None = None,
                 settings: dict[str, str] | None = None) -> list[list[Any]]:
    with client.connection(database).cursor() as cursor:
        _begin(cursor, isolation, settings)
        try:
            results = [_run(cursor, step["sql"], step.get("params", ())) for step in steps]
        except BaseException:
            cursor.execute("ROLLBACK")
            raise
        cursor.execute("COMMIT")
        return results


def query(client: Client, sql: str, params: Sequence[Any] = (), settings: dict[str, str] | None = None,
          database: str | None = None) -> list[Any]:
    """The json values of a query's rows."""
    return _transaction(client, [{"sql": sql, "params": params}], database, settings=settings)[0]


def value(client: Client, sql: str, params: Sequence[Any] = (), settings: dict[str, str] | None = None,
          database: str | None = None) -> Any:
    """The json value of the first row, or None."""
    rows = query(client, sql, params, settings, database)
    return rows[0] if rows else None


def exists(client: Client, sql: str, params: Sequence[Any] = (), database: str | None = None) -> bool:
    return bool(value(client, sql, params, database=database))


def execute(client: Client, steps: Sequence[dict[str, Any]], database: str | None = None) -> None:
    """Statements without results (DDL) in one transaction."""
    _transaction(client, steps, database)


def transaction(client: Client, steps: Sequence[dict[str, Any]], isolation: str | None = None,
                database: str | None = None) -> list[Any]:
    """The statements of a vecDSL transaction in one PostgreSQL transaction; any failure rolls back all of them."""
    return [rows[0] if rows else None for rows in _transaction(client, steps, database, isolation)]


def autocommit(client: Client, sql: str, database: str | None = None, closes: str | None = None) -> None:
    """A statement that cannot run inside a transaction block (CREATE DATABASE, VACUUM, CREATE INDEX CONCURRENTLY)."""
    if closes is not None:
        client.forget(closes)
    client.connection(database).execute(sql)


def read_records(client: Client, location: str) -> list[dict[str, Any]]:
    """Records of a local JSON array or JSON Lines file (file:// URI or path)."""
    path = location[len("file://"):] if location.startswith("file://") else location
    with open(path, encoding="utf-8") as handle:
        text = handle.read()
    stripped = text.lstrip()
    if stripped.startswith("["):
        return json.loads(stripped)
    return [json.loads(line) for line in text.splitlines() if line.strip()]


def import_file(client: Client, sql: str, location: str, params: Sequence[Any] = (), batch_size: int = _BATCH,
                database: str | None = None) -> dict[str, int]:
    """A local file written in batches by one INSERT statement ($1 is the batch), all in one transaction."""
    records = read_records(client, location)
    steps = [{"sql": sql, "params": [records[start:start + batch_size], *params]} for start in range(0, len(records), batch_size)]
    totals: dict[str, int] = {}
    for rows in _transaction(client, steps, database):
        for key, count in (rows[0] if rows else {}).items():
            totals[key] = totals.get(key, 0) + count
    return totals
